{
  "findings": [
    {
      "title": "Contradictory exclusion criteria for positive patch test reactions",
      "page": 49,
      "quote": "Patients with a documented diagnosis of ACD of hands and/or feet, who have a positive patch test reaction at screening will also be excluded from the study, regardless of whether history of current skin exposure to products containing this allergen (current relevance) is present. ... Patients with positive reactions which are interpreted as irritant reactions based upon morphology, timing (eg, 1 +ve at day 2 followed by a decrescendo pattern) will still be eligible for study as long as they meet other eligibility criteria for the study.",
      "severity": "critical"
    },
    {
      "title": "Inconsistent study duration: 28 weeks vs 16 weeks treatment period",
      "page": 54,
      "quote": "It is recommended that patients continue the use of moisturizers throughout the study (all 28 weeks where applicable).",
      "severity": "major"
    },
    {
      "title": "Inconsistent study duration: 28 weeks vs 16 weeks treatment period",
      "page": 59,
      "quote": "Treatment with the following concomitant medications is prohibited during the study treatment period (through week 16):",
      "severity": "major"
    },
    {
      "title": "Randomization caps inconsistent with total sample size",
      "page": 57,
      "quote": "Approximately 130 patients will be randomized in a 1:1 ratio ... Randomization will be capped for the adults at approximately 100. ... The number of patients with hands only involvement will be capped at approximately 100.",
      "severity": "major"
    },
    {
      "title": "Missing definition of 'adults' and 'adolescents' in dosing section",
      "page": 53,
      "quote": "in adults; dupilumab 300 mg, after a loading dose of 600 mg on day 1, irrespective of body weight - in adolescents; Body weight ≥60 kg, dupilumab 300 mg, after a loading dose of 600 mg on day 1, body weight <60 kg, dupilumab 200 mg, after a loading dose of 400 mg on day 1.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 11.4.3",
      "page": 55,
      "quote": "Data from patients who receive rescue treatment as per this adjudication during the study will be treated for efficacy analysis purposes as outlined in Section 11.4.3.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 9.1.2",
      "page": 53,
      "quote": "Patient who are withdrawn prematurely from the study will be asked to complete the early termination visit, as described in Section 9.1.2.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 8.4.2",
      "page": 53,
      "quote": "Rules for discontinuation of study treatment (permanent or temporary) are discussed in Section 8.4.2.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 8.10.1",
      "page": 56,
      "quote": "Treatment with a live attenuated vaccine (refer to Section 8.10.1 for details)",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 10.2.1 and 10.2.4",
      "page": 57,
      "quote": "All injection reactions must be reported as AEs (as defined in Section 10.2.1) and graded using the grading scales as instructed in Section 10.2.4 .",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 8.6",
      "page": 53,
      "quote": "Randomization is discussed in Section 8.6.",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion for hepatitis B: contradictory statements about HBcAb positive patients",
      "page": 51,
      "quote": "NOTE: Patients who have gained immunity for hepatitis B virus infection after vaccination (patients who are HBsAg negative, hepatitis B surface antibody [HBsAb] positive, and HBcAb negative) or after natural infection (patients who are HBsAg negative, HBsAb positive, and HBcAb positive) are eligible for the study. ... In case of results showing HBsAg negative, HBsAb negative, and HBcAb positive, a HBV DNA testing will be performed prior to randomization to rule out a false positivity and to confirm current infection. Patients who are HBcAb positive and HBV DNA negative will be eligible to enroll in the trial.",
      "severity": "major"
    }
  ]
}
